//! Snowball 3.1.1 stemmers (English, Portuguese), generated by the official Snowball compiler.
//! See `VENDOR.md`. The only hand-written file is this one.

pub mod snowball;

use std::borrow::Cow;

use snowball::SnowballEnv;

/// The two languages vendored here.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Algorithm {
    English,
    Portuguese,
}

/// The stem of `word` (expected lower case, NFC).
pub fn stem(algorithm: Algorithm, word: &str) -> Cow<'_, str> {
    let mut env = SnowballEnv::create(word);
    match algorithm {
        Algorithm::English => snowball::algorithms::english_stemmer::stem(&mut env),
        Algorithm::Portuguese => snowball::algorithms::portuguese_stemmer::stem(&mut env),
    };
    env.get_current()
}
